// Auto-composed skeleton for AdminDashboard
// Pattern: aggregator
// Stubs: none

// Pattern: Aggregator (Approach 3 — pre-written body with parameters)
// responsibility: Fold/reduce over a collection to produce a summary value
// test: Sum([1, 2, 3, 4, 5]) returns 15
// test: Max([3, 7, 2, 9, 1]) returns 9
// test: Count([true, false, true, true]) returns 3
//
// Parameters:
//   operation: the fold operation (Sum, Max, Min, Count, Average)
//   initialValue: the starting accumulator value

// Sum of a sequence of integers
method Sum(values: seq<int>) returns (total: int)
  requires |values| > 0
  ensures total == SumSeq(values)
  decreases |values|
{
  total := SumSeq(values);
}

// Maximum value in a sequence
method Max(values: seq<int>) returns (maxVal: int)
  requires |values| > 0
  ensures maxVal == MaxSeq(values)
  decreases |values|
{
  maxVal := MaxSeq(values);
}

// Count elements satisfying a predicate (count of positive numbers)
method CountPositive(values: seq<int>) returns (count: int)
  ensures count >= 0
  ensures count <= |values|
  decreases |values|
{
  count := 0;
  var i := 0;
  while i < |values|
    invariant 0 <= i <= |values|
    invariant count <= i
    decreases |values| - i
  {
    if values[i] > 0 {
      count := count + 1;
    }
    i := i + 1;
  }
}

// Helper: sum of a sequence (used in postcondition)
function SumSeq(values: seq<int>): int
  decreases |values|
{
  if |values| == 0 then 0
  else values[0] + SumSeq(values[1..])
}

// Helper: max of a non-empty sequence
function MaxSeq(values: seq<int>): int
  requires |values| > 0
  decreases |values|
{
  if |values| == 1 then values[0]
  else if values[0] >= MaxSeq(values[1..]) then values[0]
  else MaxSeq(values[1..])
}

// Auto-composed skeleton for AuditLog
// Pattern: repository
// Stubs: none

include "result.dfy"

// Pattern: Repository (Approach 3 — pre-written body with parameters)
// responsibility: Store items with ID uniqueness, lookup, and update
// test: Add([], Record(1, "test", "data")) returns Success([Record(1, "test", "data")])
// test: Add([Record(1, "a", "b")], Record(1, "c", "d")) returns Failure("duplicate id")
//
// Parameters:
//   idField: string — name of the ID field (for error messages)
//   allowUpdate: bool — whether Add replaces existing IDs (default false)

include "result.dfy"

datatype Entity =
  | Record(id: int, name: string, data: string)

// Invariant: no duplicate IDs
predicate NoDuplicates(items: seq<Entity>)
{
  forall i, j :: 0 <= i < j < |items| ==> items[i].id != items[j].id
}

// Add: insert if ID not present, fail if duplicate
method Add(items: seq<Entity>, entity: Entity) returns (result: Result<seq<Entity>>)
  requires NoDuplicates(items)
  ensures result.Success? ==> |result.value| == |items| + 1
  ensures result.Failure? ==> result.error == "duplicate id"
  decreases |items|
{
  var i := 0;
  var found := false;
  while i < |items| && !found
    invariant 0 <= i <= |items|
    invariant NoDuplicates(items)
    decreases |items| - i
  {
    if items[i].id == entity.id {
      found := true;
    }
    i := i + 1;
  }

  if found {
    result := Failure("duplicate id");
  } else {
    result := Success(items + [entity]);
  }
}

// Find: lookup by ID
method Find(items: seq<Entity>, id: int) returns (result: Result<Entity>)
  ensures result.Success? ==> result.value.id == id
  decreases |items|
{
  var i := 0;
  while i < |items|
    invariant 0 <= i <= |items|
    decreases |items| - i
  {
    if items[i].id == id {
      result := Success(items[i]);
      return;
    }
    i := i + 1;
  }
  result := Failure("not found");
}

// Remove: delete by ID
method Remove(items: seq<Entity>, id: int) returns (result: Result<seq<Entity>>)
  requires NoDuplicates(items)
  ensures result.Success? ==> |result.value| <= |items|
  decreases |items|
{
  var i := 0;
  var found := false;
  while i < |items| && !found
    invariant 0 <= i <= |items|
    decreases |items| - i
  {
    if items[i].id == id {
      found := true;
    }
    i := i + 1;
  }

  if found {
    var newItems := [];
    var j := 0;
    while j < |items|
      invariant 0 <= j <= |items|
      invariant |newItems| <= j
      decreases |items| - j
    {
      if items[j].id != id {
        newItems := newItems + [items[j]];
      }
      j := j + 1;
    }
    result := Success(newItems);
  } else {
    result := Failure("not found");
  }
}

